#!/usr/bin/env bash
#
# Render the Homebrew formula for `gizmo` to stdout.
#
# The release workflow (.github/workflows/release.yml) runs this after it has
# built the per-platform archives and computed their SHA-256 checksums. The
# output is written into the tap repo as Formula/gizmo.rb so users can run:
#
#     brew install acme/tap/gizmo
#
# Required environment variables:
#   VERSION            release version without the leading "v" (e.g. 1.2.3)
#   SHA_DARWIN_AMD64   sha256 of gizmo_<version>_darwin_amd64.tar.gz
#   SHA_DARWIN_ARM64   sha256 of gizmo_<version>_darwin_arm64.tar.gz
#   SHA_LINUX_AMD64    sha256 of gizmo_<version>_linux_amd64.tar.gz
#   SHA_LINUX_ARM64    sha256 of gizmo_<version>_linux_arm64.tar.gz
#
# Optional (sensible defaults for github.com/acme/gizmo):
#   OWNER  REPO  DESC  HOMEPAGE
set -euo pipefail

: "${VERSION:?VERSION is required}"
: "${SHA_DARWIN_AMD64:?SHA_DARWIN_AMD64 is required}"
: "${SHA_DARWIN_ARM64:?SHA_DARWIN_ARM64 is required}"
: "${SHA_LINUX_AMD64:?SHA_LINUX_AMD64 is required}"
: "${SHA_LINUX_ARM64:?SHA_LINUX_ARM64 is required}"

OWNER="${OWNER:-acme}"
REPO="${REPO:-gizmo}"
DESC="${DESC:-Do the thing across all your repos.}"
HOMEPAGE="${HOMEPAGE:-https://github.com/${OWNER}/${REPO}}"
BASE_URL="https://github.com/${OWNER}/${REPO}/releases/download/v${VERSION}"

cat <<EOF
# typed: false
# frozen_string_literal: true

# This file is generated by the gizmo release workflow. Do not edit by hand.
class Gizmo < Formula
  desc "${DESC}"
  homepage "${HOMEPAGE}"
  version "${VERSION}"

  on_macos do
    on_arm do
      url "${BASE_URL}/gizmo_${VERSION}_darwin_arm64.tar.gz"
      sha256 "${SHA_DARWIN_ARM64}"
    end
    on_intel do
      url "${BASE_URL}/gizmo_${VERSION}_darwin_amd64.tar.gz"
      sha256 "${SHA_DARWIN_AMD64}"
    end
  end

  on_linux do
    on_arm do
      url "${BASE_URL}/gizmo_${VERSION}_linux_arm64.tar.gz"
      sha256 "${SHA_LINUX_ARM64}"
    end
    on_intel do
      url "${BASE_URL}/gizmo_${VERSION}_linux_amd64.tar.gz"
      sha256 "${SHA_LINUX_AMD64}"
    end
  end

  def install
    bin.install "gizmo"
  end

  test do
    system "#{bin}/gizmo", "--version"
  end
end
EOF
